use rune::{col, el, El, Phase, SurfaceFit};
use crate::State;
use super::{floating_pills, theme::CANVAS};
pub fn view(s:&State)->El { let mut v=col().w_full().grow(1.0).min_w(0.0).min_h(0.0).center().fill(CANVAS).clip_soft(0.0).child(el().key("image").w_full().h_full().pixels_fit(&s.image,SurfaceFit::Fit).scale(s.zoom).offset(s.pan_x,s.pan_y).rotate((s.rotation as f32).to_radians()).on_wheel(|s:&mut State,e,_|{match e.dy.partial_cmp(&0.0){Some(std::cmp::Ordering::Greater)=>s.zoom=(s.zoom*1.15).min(8.0),Some(std::cmp::Ordering::Less)=>s.zoom=(s.zoom/1.15).max(0.10),_=>{}}if s.zoom<=1.0{s.zoom=s.zoom.max(0.10);s.pan_x=0.0;s.pan_y=0.0;}true}).on_drag(|s:&mut State,d,_|{if s.zoom<=1.0{return;}if d.phase==Phase::Down{s.drag_pan_x=s.pan_x;s.drag_pan_y=s.pan_y;}let fit=if s.image_width>0&&s.image_height>0{(800.0/s.image_width as f32).min(500.0/s.image_height as f32)}else{1.0};let width=s.image_width as f32*fit*s.zoom;let height=s.image_height as f32*fit*s.zoom;let max_x=((width-800.0)/2.0).max(0.0);let max_y=((height-500.0)/2.0).max(0.0);s.pan_x=(s.drag_pan_x+d.dx).clamp(-max_x,max_x);s.pan_y=(s.drag_pan_y+d.dy).clamp(-max_y,max_y);})); v=v.child(floating_pills::view(s)); if s.zoom_menu{v=v.child(floating_pills::zoom_menu().pin(None,None,Some(8.0),Some(54.0)));} v }
